def seed_reference_data() -> None:
    """Known master data only; never infer a code for an existing legacy unit."""
    connection = op.get_bind()
    categories = sa.table('categorias_insumo', sa.column('id'), sa.column('nombre'), sa.column('activo', sa.Boolean()))
    names = set(connection.scalars(sa.select(categories.c.nombre)))
    general = connection.scalar(sa.select(categories.c.id).where(
        sa.func.lower(categories.c.nombre) == 'general', categories.c.activo == sa.true()))
    if general is None:
        name, number = 'General', 1
        while name in names:
            name = 'General WALOS' + (f' {number}' if number > 1 else '')
            number += 1
        connection.execute(categories.insert().values(nombre=name, activo=True))
    units = sa.table('unidades_medida', sa.column('id'), sa.column('nombre'), sa.column('dimension'),
                     sa.column('factor', sa.Numeric(18, 6)), sa.column('activo', sa.Boolean()), sa.column('codigo_ui'))
    names = set(connection.scalars(sa.select(units.c.nombre)))
    for code, label, dimension, factor in [('UNIDAD', 'Unidad', 'conteo', 1),
                                          ('KILOGRAMO', 'Kilogramo', 'masa', 1000)]:
        if connection.scalar(sa.select(units.c.id).where(units.c.codigo_ui == code)) is not None:
            continue
        name, number = label + ' WALOS', 2
        while name in names:
            name = f'{label} WALOS {number}'
            number += 1
        connection.execute(units.insert().values(nombre=name, dimension=dimension, factor=factor,
                                                activo=True, codigo_ui=code))
        names.add(name)


